cpp.source:
int accumulate(int a, int b) { const int first = a + b; int result = (first * 2); result = result + b; return result; }
bool condition(int a, int b) { bool flag = a < b; bool result = !flag || a == b; return result; }
int converted(bool a) { const int result = static_cast<int>(a); return result + 1; }

rust.source:
fn accumulate(a: i32, b: i32) -> i32 { let first: i32 = a + b; let mut result: i32 = (first * 2); result = result + b; result }
fn condition(a: i32, b: i32) -> bool { let flag: bool = a < b; let result: bool = !flag || a == b; result }
fn converted(a: bool) -> i32 { let result: i32 = a as i32; result + 1 }

