func accumulate(a: int, b: int) -> int:
    var first: int = a + b
    var result: int = (first * 2)
    result = result + b
    return result
func condition(a: int, b: int) -> bool:
    var flag: bool = a < b
    var result: bool = not flag or a == b
    return result
func converted(a: bool) -> int:
    var result: int = int(a)
    return result + 1

